test_suite:
test('starts at the target value on first render', () => {
  const { result } = renderHook(() => useSpring(100));
  expect(typeof result.current).toBe('number');
});

test('returns a number', () => {
  const { result } = renderHook(() => useSpring(50, { stiffness: 0.2, damping: 0.7 }));
  expect(typeof result.current).toBe('number');
});

test('moves toward target when target changes', () => {
  const { result, rerender } = renderHook(
    ({ t }) => useSpring(t, { stiffness: 0.5, damping: 0.5 }),
    { initialProps: { t: 0 } }
  );
  const initial = result.current;
  rerender({ t: 200 });
  expect(result.current).toBeGreaterThanOrEqual(initial);
});

test('uses default config without crashing', () => {
  const { result } = renderHook(() => useSpring(42));
  expect(() => result.current).not.toThrow();
});

// __hidden__
test('value is finite number', () => {
  const { result } = renderHook(() => useSpring(75, { stiffness: 0.1, damping: 0.9 }));
  expect(isFinite(result.current)).toBe(true);
});

solution:
import { useState, useEffect, useRef } from 'react';

interface SpringConfig {
  stiffness?: number;
  damping?: number;
}

export function useSpring(target: number, config: SpringConfig = {}): number {
  const { stiffness = 0.1, damping = 0.8 } = config;
  const [value, setValue] = useState(target);
  const velocity = useRef(0);
  const currentValue = useRef(target);
  const rafId = useRef<number>(0);

  useEffect(() => {
    const animate = () => {
      const force = (target - currentValue.current) * stiffness;
      velocity.current = (velocity.current + force) * damping;
      currentValue.current += velocity.current;
      setValue(currentValue.current);
      if (Math.abs(target - currentValue.current) > 0.01 || Math.abs(velocity.current) > 0.01) {
        rafId.current = requestAnimationFrame(animate);
      }
    };
    rafId.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(rafId.current);
  }, [target, stiffness, damping]);

  return value;
}
